<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Builder; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class Pago extends Model { protected $fillable=['idempotency_key','numero_recibo','cliente_id','metodo_pago_id','estado_pago_id','monto','moneda','referencia','referencia_externa','pagado_at','procesado_por','observaciones']; protected function casts(): array { return ['monto'=>'decimal:2','pagado_at'=>'datetime']; } public function scopePagados(Builder $query): Builder { return $query->whereNotNull('pagado_at'); } public function scopeEntreFechas(Builder $query,$desde,$hasta): Builder { return $query->whereBetween('pagado_at',[$desde,$hasta]); } public function cliente(): BelongsTo { return $this->belongsTo(Cliente::class); } public function metodo(): BelongsTo { return $this->belongsTo(MetodoPago::class,'metodo_pago_id'); } public function estado(): BelongsTo { return $this->belongsTo(EstadoPago::class,'estado_pago_id'); } public function procesadoPor(): BelongsTo { return $this->belongsTo(User::class,'procesado_por'); } public function aplicaciones(): HasMany { return $this->hasMany(AplicacionPago::class); } public function reembolsos(): HasMany { return $this->hasMany(Reembolso::class); } public function historialEstados(): HasMany { return $this->hasMany(HistorialEstadoPago::class); } public function estaPagado(): bool { return $this->pagado_at!==null; } }
